 auto frame_doc=initial;entry(frame_doc).gradient->start_x.literal+=1;valid(frame_doc);frame=Session(frame_doc);auto identity_doc=initial;entry(identity_doc).gradient->id="replacement-gradient";valid(identity_doc);identity=Session(identity_doc);auto payload_doc=initial;for(auto& s:entry(payload_doc).gradient->stops)if(s.id=="middle")s.rgba[0].literal=.7;valid(payload_doc);payload=Session(payload_doc);auto missing_stop_doc=initial;for(auto& s:entry(missing_stop_doc).gradient->stops)if(s.id=="middle")s.id="replacement-middle";valid(missing_stop_doc);missing_stop=Session(missing_stop_doc);
 auto missing_entry_doc=initial;auto& stack=missing_entry_doc.objects.at("built").stack;stack.erase(std::remove_if(stack.begin(),stack.end(),[](const auto& e){return e.id=="fill";}),stack.end());valid(missing_entry_doc);auto removal=base;removal.apply({RemoveOperation{"built","fill"}},0);check(removal.document()==missing_entry_doc,"Independent whole missing entry native agrees canonical removal BEFORE Window");missing_entry=Session(missing_entry_doc);auto missing_owner_doc=initial;missing_owner_doc.objects.erase("built");auto& roots=missing_owner_doc.compositions.at(0).roots;roots.erase(std::remove(roots.begin(),roots.end(),"built"),roots.end());valid(missing_owner_doc);auto deletion=base;deletion.apply({DeleteObjects{{"built"}}},0);check(deletion.document()==missing_owner_doc,"Independent whole missing owner native agrees canonical deletion BEFORE Window");missing_owner=Session(missing_owner_doc);
 const Session* caller=&base;QString code;if(context==0){caller=&replacement;code="SESSION_CONFLICT";}if(context==1)code="SESSION_CONFLICT";if(context==2){caller=&changed;code="REVISION_CONFLICT";}if(context==3){caller=&active;code="GESTURE_ACTIVE";}if(context==4){caller=&cancelled;code="REVISION_CONFLICT";}if(context==5){caller=&cancelled;code="GESTURE_ACTIVE";}if(context==6){caller=&frame;code="PROPERTY_CONFLICT";}if(context==7){caller=&identity;code="PROPERTY_CONFLICT";}if(context==8){caller=&payload;code="PROPERTY_CONFLICT";}if(context==9){caller=&missing_stop;code="PROPERTY_CONFLICT";}if(context==10){caller=&missing_entry;code="PROPERTY_CONFLICT";}if(context==11){caller=&missing_owner;code="PROPERTY_CONFLICT";}
 const auto path=root+"/mode-"+QString::number(mode);write(path+"-expected.nect",caller->document());QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-recovery",std::make_unique<FolderLibrary>(settings),&settings);w.host.session=context==5?active:base;w.host.edited();w.resize(1400,1100);w.show();events();w.canvas->set_selection("built");events();auto* dock=w.findChild<QDockWidget*>("properties");check(dock,"Properties exists");dock->show();dock->raise();events();QPointer<QPushButton> producer=control<QPushButton>(w,"gradient-stop-add-fill");reveal(producer);const auto sid=w.host.session_id;w.host.session=*caller;if(context==1)w.host.session_id+="-other";same(w.host.session,*caller);QSignalSpy emitted(producer,&QPushButton::clicked);bool escaped=false;QString exception;try{producer->click();}catch(const std::exception& e){escaped=true;exception=QString::fromUtf8(e.what());}events();const auto status=w.statusBar()->currentMessage();write(path+"-observed.nect",w.host.session.document());check(w.grab().save(path+"-status.png"),"Actual original stale add producer Window rendered");QJsonObject state{{"escaped_exception",escaped},{"exception",exception},{"signal_count",emitted.count()},{"status",status},{"document_equal",w.host.session.document()==caller->document()},{"history_equal",w.host.session.history()==caller->history()}};QFile metadata(path+"-producer.json");check(metadata.open(QIODevice::WriteOnly|QIODevice::NewOnly),"Original producer readback immutable");metadata.write(QJsonDocument(state).toJson());metadata.close();std::cout<<"GRADIENT_STOP_ADD mode="<<mode<<" context="<<context<<" status="<<status.toStdString()<<" doc_equal="<<(w.host.session.document()==caller->document())<<" history_equal="<<(w.host.session.history()==caller->history())<<" escaped="<<escaped<<"\n";same(w.host.session,*caller);check(!escaped&&emitted.count()==1,"One actual original stale add button/no escaped exception");check(status.startsWith(code+": "),"Stale original add producer reports precise context refusal without authoring");
 if(!w.host.session.gesture_active()){w.host.save(path+"-saved.nect");w.host.flush();events();same(w.host.session,*caller);check(read(path+"-saved.nect")==read(path+"-expected.nect")&&QFile::copy(path+"-saved.nect",path+"-snapshot.nect"),"Actual immutable native preserves whole caller/Gradient/stop/source state");}else{check(read(path+"-observed.nect")==read(path+"-expected.nect")&&QFile::copy(path+"-observed.nect",path+"-snapshot.nect"),"Actual committed native encode/caller active preview preserved; activeHostSaveNOT_RUN");same(w.host.session,*caller);}if(w.host.session.gesture_active())w.host.session.cancel_gesture();w.host.session_id=sid;w.close();events();
